    function getAccessToken($clientId, $secret) {
        $url = "https://api-m.sandbox.paypal.com/v1/oauth2/token";
    
        $headers = [
            "Accept: application/json",
            "Accept-Language: en_US",
            "Content-Type: application/x-www-form-urlencoded"
        ];
    
        $postFields = "grant_type=client_credentials";
    
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        curl_setopt($ch, CURLOPT_USERPWD, "$clientId:$secret");
        curl_setopt($ch, CURLOPT_POSTFIELDS, $postFields);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('Curl error: ' . curl_error($ch));
        }
    
        curl_close($ch);
        $result = json_decode($response, true);
        return $result['access_token'];
    }
    
    function sendPayout($accessToken, $receiverEmail, $amount, $currency = 'USD') {
        $url = "https://api-m.sandbox.paypal.com/v1/payments/payouts";
    
        $batchId = uniqid('batch_');
        $itemId = uniqid('item_');
    
        $data = [
            "sender_batch_header" => [
                "sender_batch_id" => $batchId,
                "email_subject" => "Bạn đã nhận được chiết khấu hoàn lại"
            ],
            "items" => [[
                "recipient_type" => "EMAIL",
                "amount" => [
                    "value" => number_format($amount, 2, '.', ''),
                    "currency" => $currency
                ],
                "receiver" => $receiverEmail,
                "note" => "Chiết khấu hoàn lại từ đơn hàng",
                "sender_item_id" => $itemId
            ]]
        ];
    
        $headers = [
            "Content-Type: application/json",
            "Authorization: Bearer $accessToken"
        ];
    
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('Curl error: ' . curl_error($ch));
        }
    
        curl_close($ch);
        return json_decode($response, true);
    }

    function getPayoutStatus($accessToken, $payoutBatchId) {
        $url = "https://api-m.sandbox.paypal.com/v1/payments/payouts/$payoutBatchId";
    
        $headers = [
            "Content-Type: application/json",
            "Authorization: Bearer $accessToken"
        ];
    
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('Curl error: ' . curl_error($ch));
        }
    
        curl_close($ch);
        return json_decode($response, true);
    }
    
